import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container for this node
  const root = new Group();

  // Determine reasonable plane dimensions.
  // Using the image aspect ratio (512 / 320 = 1.6) as a guide.
  const PLANE_WIDTH = 1.6;
  const PLANE_HEIGHT = 1.0;

  const geometry = new PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT);
  const material = new MeshBasicNodeMaterial();

  const planeMesh = new Mesh(geometry, material);
  root.add(planeMesh);

  // Load the texture if an image URL is provided.
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        material.map = tex;
        material.needsUpdate = true;
      })
      .catch(() => {
        // Silently ignore texture load failures; the plane will remain untextured.
      });
  }

  // No cinematic primitives for this node, but keep the pattern for future extensions.
  const primitiveInstances = [];

  // Cleanup function to dispose resources and kill any timelines (none here).
  const cleanup = () => {
    // Dispose material and geometry.
    material.dispose();
    geometry.dispose();

    // Dispose any primitive resources.
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    });

    // Kill all GSAP timelines that might have been created (none in this node).
    gsap.globalTimeline.clear();
  };

  // Attach handlers container (empty because no interactions are defined).
  root.userData = {
    handlers: {},
    cleanup,
  };

  return root;
}
